#pragma once
#include <queue>
#include <string>
#include <vector>

struct Item {
    int priority;
    std::string value;
};

struct ItemCompare {
    bool operator()(const Item& a, const Item& b) const {
        return a.priority > b.priority;
    }
};

class StablePriorityQueue {
public:
    void push(int priority, const std::string& value) {
        heap_.push(Item{priority, value});
    }

    std::string pop() {
        Item top = heap_.top();
        heap_.pop();
        return top.value;
    }

private:
    std::priority_queue<Item, std::vector<Item>, ItemCompare> heap_;
};

