#pragma once
#include <queue>
#include <string>
#include <vector>

struct Item {
    int priority;
    long long order;
    std::string value;
};

struct ItemCompare {
    bool operator()(const Item& a, const Item& b) const {
        if (a.priority != b.priority) return a.priority > b.priority;
        return a.order > b.order;
    }
};

class StablePriorityQueue {
public:
    void push(int priority, const std::string& value) {
        heap_.push(Item{priority, counter_++, value});
    }

    std::string pop() {
        Item top = heap_.top();
        heap_.pop();
        return top.value;
    }

private:
    long long counter_ = 0;
    std::priority_queue<Item, std::vector<Item>, ItemCompare> heap_;
};

