test_setup_files.test_stable_priority_queue.cpp:
#include "stable_priority_queue.h"
#include <cassert>
#include <iostream>

int main() {
    {
        StablePriorityQueue q;
        q.push(5, "low");
        q.push(1, "high");
        q.push(3, "mid");
        assert(q.pop() == "high");
        assert(q.pop() == "mid");
        assert(q.pop() == "low");
    }
    {
        StablePriorityQueue q;
        for (int i = 0; i < 20; i++) {
            q.push(1, std::string(1, (char)('a' + i)));
        }
        for (int i = 0; i < 20; i++) {
            std::string want(1, (char)('a' + i));
            assert(q.pop() == want);
        }
    }
    std::cout << "PASS" << std::endl;
    return 0;
}
